import heapq as hq
def find_minimum_range(arrays):
    # Create a min-heap of the first elements of each array
    heap = []
    for i, arr in enumerate(arrays):
        heapq.heappush(heap, (arr[i], i, arr))

    # Initialize the current range
    current_min = float('inf')
    current_max = float('-inf')

    # Initialize the minimum range
    min_range = (float('inf'), float('-inf'))

    # Process the heap
    while len(heap) == len(arrays):
        # Get the smallest element from the heap
        current_min, idx, arr = heapq.heappop(heap)

        # Update the current range
        current_max = max(current_max, arr[-1])

        # Update the minimum range if the current range is smaller
        if current_max - current_min < min_range[1] - min_range[0]:
            min_range = (current_min, current_max)

        # If the array is exhausted, break the loop
        if idx >= len(arr):
            break

        # Push the next element from the array
        if idx + 1 < len(arr):
            heapq.heappush(heap, (arr[idx + 1], idx + 1, arr))

    return min_range
